import express from 'express';

const app = express();
// 1. Sem este middleware, req.body chega vazio (o corpo é texto cru).
app.use(express.json());

// 2. A portaria: uma função só com as regras, longe da rota.
function validarProduto(dados) {
  const erros = [];
  if (typeof dados?.nome !== 'string' || dados.nome.trim() === '') {
    erros.push('nome é obrigatório');
  }
  if (typeof dados?.preco !== 'number' || !Number.isFinite(dados.preco) || dados.preco < 0) {
    erros.push('preco deve ser um número maior ou igual a zero');
  }
  return erros;
}

app.post('/api/produtos', (req, res) => {
  // 3. Conferir ANTES de usar: este é o momento mais importante da rota.
  const erros = validarProduto(req.body);
  if (erros.length > 0) {
    // 4. 400 avisa que o PROBLEMA É DO PEDIDO — com a lista para corrigir.
    return res.status(400).json({ erros });
  }
  // 5. Dado conferido: aqui entraríamos no banco de verdade.
  res.status(201).json({ criado: req.body.nome.trim() });
});

app.get('/api/produtos', (req, res) => {
  // 6. Query também é entrada: req.query.semEstoque chega como texto 'true'.
  const filtro = req.query.semEstoque === 'true';
  res.json({ aviso: 'filtro aplicado: ' + filtro });
});

app.listen(3000);
